    const antibody=document.querySelector('.panel-antibody > span');if(antibody)antibody.innerHTML='<span class="comic-word">MONOCLONAL</span><span class="comic-word">ANTIBODY</span>';
    const fitPopupTitle=()=>{const h=document.getElementById('infoTitle')||document.querySelector('.info-card h3');if(!h)return;const card=h.closest('.info-card');if(!card)return;const max=innerWidth<=390?24:innerWidth<=520?27:innerWidth<=760?32:38,min=12;h.style.setProperty('font-size',max+'px','important');h.style.setProperty('letter-spacing','-0.4px','important');h.style.setProperty('white-space','nowrap','important');const available=Math.max(80,card.clientWidth-parseFloat(getComputedStyle(card).paddingLeft)-parseFloat(getComputedStyle(card).paddingRight)-52);let size=max;while(size>min&&h.scrollWidth>available){size-=1;h.style.setProperty('font-size',size+'px','important')}};
    document.querySelectorAll('.comic-panel').forEach(panel=>panel.addEventListener('click',()=>requestAnimationFrame(()=>requestAnimationFrame(fitPopupTitle))));const infoTitle=document.getElementById('infoTitle');if(infoTitle)new MutationObserver(()=>requestAnimationFrame(fitPopupTitle)).observe(infoTitle,{childList:true,characterData:true,subtree:true});addEventListener('resize',()=>requestAnimationFrame(fitPopupTitle));fitPopupTitle();initFirstPageDNA();
